mapper.select:
select r.* from sys_role r join sys_user_role ur on r.id = ur.role_id where r.state = 1 and ur.user_id = #{userId}
union select * from sys_role where state = 1 and create_user = #{account}
order by sort

select r.*
from sys_role r
join sys_user_role ur on r.id = ur.role_id


        and r.name like concat(#{po.name},'%')


        and r.code like concat(#{po.code},'%')


        and r.state=#{po.state}

    and ur.user_id=#{po.id}

union
select * from sys_role
where create_user=#{po.createUser}

    and state=#{po.state}

order by sort
